contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint dep) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(address(this).balance >= dep, "insufficient balance");

        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: dep}(); if (__ESBMC_reverted()) return;

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        uint contractBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;

        bool firstReverted;
        c.Collect(balBefore); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;

        assert(
            !firstReverted &&
            balAfter == 0 &&
            contractBalAfter == contractBalBefore - balBefore &&
            thisBalAfter == thisBalBefore + balBefore
        );
    }

    receive() external payable {}
}

