pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 dep) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= dep);
        try c.SetMinSum(0) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: dep}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint contractBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;
        bool firstReverted;
        try c.Collect(balBefore) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint contractBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;
        assertTrue(!firstReverted &&
            balAfter == 0 &&
            contractBalAfter == contractBalBefore - balBefore &&
            thisBalAfter == thisBalBefore + balBefore);
    }

    function testFuzz_run(uint256 dep) public {
        _run(dep);
    }

    receive() external payable {}
}
